import type { Dispatch, RefObject, SetStateAction } from 'react';
import type { parseConversation } from '../../intake/parse-conversation';

type Props = {
  conversationOpen: boolean; alias: string; setAlias: Dispatch<SetStateAction<string>>;
  selected: string; examples: Record<string, string>; choose: (name: string) => void;
  view: 'reading' | 'edit'; setView: Dispatch<SetStateAction<'reading' | 'edit'>>;
  source: string; setSource: Dispatch<SetStateAction<string>>; parsed: ReturnType<typeof parseConversation>;
  editorRef: RefObject<HTMLTextAreaElement | null>; loading: boolean; hasResult: boolean; analyze: () => void;
  scenario: { description: string } | null; loadRandom: () => void;
};
export function ConversationPanel({ conversationOpen, alias, setAlias, selected, examples, choose, view, setView, source, setSource, parsed, editorRef, loading, hasResult, analyze, scenario, loadRandom }: Props) {
  return <section className="surface" id="conversation-panel" aria-label="Entrada de conversación" hidden={!conversationOpen}><div className="surface-header"><div><h2>Conversación</h2><p>Fuente original del expediente temporal</p></div><span className="tiny-pill">Entrada manual</span></div><div className="source-head"><label className="field-label" htmlFor="alias">Alias del expediente</label><div className="case-row"><input id="alias" className="alias" value={alias} maxLength={45} onChange={e => setAlias(e.target.value)} /><span className="source-meta">Sesión temporal</span></div><div className="example-head"><span className="field-label">Ejemplos ficticios</span><span>O pega tu propio texto</span></div><div className="examples">{Object.keys(examples).map(name => <button key={name} className={`example-btn ${selected === name ? 'active' : ''}`} onClick={() => choose(name)}>{name === 'Libre' ? 'Texto libre' : name}</button>)}</div></div>
        {selected === 'Libre' && <div className="scenario-picker"><button type="button" className="secondary" disabled={loading} onClick={loadRandom}>Cargar conversación aleatoria</button><p role="status">{scenario ? <><strong>Qué observar:</strong> {scenario.description}</> : 'Carga un escenario ficticio del repositorio para explorar la herramienta.'}</p></div>}<div className="tabs"><button className={`tab ${view === 'reading' ? 'active' : ''}`} onClick={() => setView('reading')}>Conversación</button><button className={`tab ${view === 'edit' ? 'active' : ''}`} onClick={() => setView('edit')}>Editar texto</button></div><div className="conversation-body">{view === 'edit' ? <div className="editor-wrap active"><textarea ref={editorRef} className="editor" aria-label="Texto original de la conversación" value={source} onChange={e => setSource(e.target.value)} /><p className="editor-help">Marca los turnos con «Cliente:» y «Libeen:» o «Asesor:». Las continuaciones deben ir indentadas.</p></div> : parsed.ok ? parsed.messages.map(m => <div key={m.id} id={`message-${m.id}`} tabIndex={-1} className={`chat-row ${m.role === 'advisor' ? 'advisor' : ''}`}><span className="msg-avatar">{m.role === 'advisor' ? 'L' : 'C'}</span><div className="chat-inner"><div className="msg-meta">{m.role === 'advisor' ? 'Asesor' : 'Cliente'} · Fuente {m.id}</div><div className="bubble">{m.text ?? '[Audio sin transcripción]'}</div></div></div>) : <p>Abre «Editar texto» para introducir turnos con autor identificable.</p>}</div><div className="source-footer"><div className="source-action"><button className="primary" disabled={loading || !source.trim()} onClick={analyze}>{loading ? 'Analizando…' : hasResult ? 'Reanalizar conversación ↗' : 'Analizar conversación ↗'}</button><button className="secondary" onClick={() => { setSource(source + (source.trim() ? '\n\n' : '') + 'Cliente: '); setView('edit'); requestAnimationFrame(() => { editorRef.current?.focus(); editorRef.current?.setSelectionRange(editorRef.current.value.length, editorRef.current.value.length); }); }}>+ Añadir continuación</button></div><p className="tiny-note">Solo datos ficticios. La conversación se envía al proveedor de análisis; no se envía ningún mensaje al cliente.</p></div></section>;
}

