 const preview=page.getByLabel('Vista previa de ficha CRM'); await expect(preview).toHaveValue(/3\.600 €/); await page.getByRole('button',{name:'Copiar ficha CRM'}).click(); const copied=await page.evaluate(() => navigator.clipboard.readText()); expect(copied).toBe(await preview.inputValue()); expect(copied).toContain('3.600 €'); expect(copied).toContain('CRM');
 await page.screenshot({path:'docs/current/evaluation/desktop-result.png',fullPage:true}); await page.getByRole('button',{name:'Ver conversación'}).click(); await page.getByRole('button',{name:'Editar texto'}).click(); await page.getByLabel('Texto original de la conversación').fill('Cliente: conversación ficticia nueva'); await expect(page.getByText(/resultado anterior no está actualizado/)).toBeVisible(); await page.getByRole('button',{name:'Reanalizar conversación ↗'}).click(); await expect(page.getByRole('alert')).toContainText('provider_error'); await expect(page.getByText(/resultado anterior no está actualizado/)).toBeVisible(); await page.getByRole('button',{name:'Reanalizar conversación ↗'}).click(); await expect(page.getByText(/decisiones conservadas/)).toBeVisible();
});
